+  expect(inkFrame.safeParse(frame).success).toBe(true);
+  expect(inkFrame.safeParse({ ...frame, rgb: 0x123456 }).success).toBe(true);
+  expect(inkFrame.safeParse({ ...frame, rgb: 0x1000000 }).success).toBe(false);
+});
