647	+  PALETTE_RGB.forEach((entry, index) => {
648	+    const [er, eg, eb] = channels(entry);
649	+    const distance = (r - er) ** 2 + (g - eg) ** 2 + (b - eb) ** 2;
650	+    if (distance < bestDistance) {
651	+      best = index;
652	+      bestDistance = distance;
653	+    }
654	+  });
