import { writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { chromium, devices } from "playwright";
import { routeAccessHeaders } from "../npm-scripts/env.mjs";

const ORIGIN = "https://stallion.matthijs-f49.workers.dev";
const OUT = join(homedir(), "development", ".tmp", "stallion-width");
const PROFILES = { phone: "Pixel 7", tablet: "Galaxy Tab S9" };
const browser = await chromium.launch({ headless: true });
const errors = [];
for (const [name, device] of Object.entries(PROFILES)) {
  const context = await browser.newContext({ ...devices[device], colorScheme: "light" });
  await routeAccessHeaders(context, ORIGIN);
  const page = await context.newPage();
  page.on("console", (m) => m.type() === "error" && errors.push(`${name}: ${m.text()}`));
  page.on("pageerror", (e) => errors.push(`${name}: ${e.message}`));
  await page.goto(`${ORIGIN}/b/cagl5toewxf62ts2fn43id996`, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
  await page.waitForTimeout(2500);
  writeFileSync(join(OUT, `${name}-legacy-board.png`), await page.screenshot());
  await page.goto(`${ORIGIN}/b/widthshots${Date.now()}`, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
  const more = page.getByRole("button", { name: "More tools" });
  if (await more.isVisible()) await more.tap();
  await page.locator("[data-toolbar-flip]").tap();
  const palette = page.locator('.toolbar[data-layout="Palette"]');
  await palette.waitFor({ state: "visible", timeout: 5000 });
  await palette.getByRole("button", { name: "60 px pencil" }).tap();
  await page.waitForTimeout(500);
  writeFileSync(join(OUT, `${name}-palette.png`), await page.screenshot());
  await context.close();
}
await browser.close();
console.log(errors.length === 0 ? "console errors: 0" : errors.join("\n"));
EOF
